import {
  AdminCreateUserCommand,
  AdminAddUserToGroupCommand,
  AdminLinkProviderForUserCommand,
} from "@aws-sdk/client-cognito-identity-provider";
import { DynamoDBClient, GetItemCommand } from "@aws-sdk/client-dynamodb";

const dynamodb = new DynamoDBClient({ region: process.env.AWS_REGION });

/**
 * Domain Restriction — keep in sync with all inline implementations:
 *   - packages/admin-portal/cdk/lambda/userslist/post.mjs
 *   - packages/admin-portal/cdk/lambda/importusersworker/index.mjs
 *   - packages/service/cdk/lambda/amfa/utils/signUp.mjs
 *   - CognitoAdSync/sync-engine.js
 *
 * @param {string} email - User email address
 * @param {string[]} allowedDomains - Permitted domains (empty/null = allow all)
 * @returns {{ allowed: boolean, domain?: string, error?: string }}
 */
function validateEmailDomain(email, allowedDomains) {
  if (!allowedDomains || allowedDomains.length === 0) return { allowed: true };
  const domain = email.split('@')[1]?.toLowerCase();
  if (!domain) return { allowed: false, error: 'Invalid email format' };
  const allowed = allowedDomains.some(d => d.toLowerCase() === domain);
  if (!allowed) return { allowed: false, domain, error: 'Your login domain is not permitted.' };
  return { allowed: true, domain };
}

/** Custom error class for domain restriction failures */
class DomainRestrictionError extends Error {
  constructor(message) {
    super(message);
    this.name = 'DomainRestrictionError';
    this.code = 'DOMAIN_RESTRICTED';
  }
}

const assignApplications = async (groups, username, cognitoISP, userPoolId) => {
  return Promise.all(groups.map((group) =>
    cognitoISP.send(new AdminAddUserToGroupCommand({
      UserPoolId: userPoolId,
      GroupName: group,
      Username: username
    }))))
}

function getRandomUpper() {
    return String.fromCharCode(Math.floor(Math.random() * 26) + 65)
}

function getRandomLower() {
    return String.fromCharCode(Math.floor(Math.random() * 26) + 97)
}

function getRandomNumber() {
    return String.fromCharCode(Math.floor(Math.random() * 10) + 48)
}

function getRandomSymbol() {
    const symbols = '!@#$%^&*(){}[]=<>/,.'
    return symbols[Math.floor(Math.random() * symbols.length)]
}

const  randomFunc = {
    upper: getRandomUpper,
    lower: getRandomLower,
    number: getRandomNumber,
    symbol: getRandomSymbol
};


function generatePassword(lower, upper, number, symbol, length) {
    console.log(lower, upper, number, symbol, length)
    let generatedPassword = ''
    const typesCount = lower + upper + number + symbol
   //Object.values(item)[0] 获取数组中每个对象的值
   // 筛选出值为true(状态为选中的)的大写英文字母、小写英文字母、数字、特殊符号
    const typesArr = [{lower}, {upper}, {number}, {symbol}].filter(item => Object.values(item)[0] )
    // 状态都为未选中，则都为flase，加起来就是0；直接返回
    if(typesCount === 0) {
        return false
    }

    for(let i = 0; i < length; i +=  typesCount) {
        // 遍历循环状态为选中的对象组成的数组，获取每个对象的属性名，根据属性名调用各自生成函数
        typesArr.forEach(type => {
            const funcName = Object.keys(type)[0]
            generatedPassword += randomFunc[funcName]()
        })
    }
    // 截取选择的密码位数长度的随机密码
    const finalPassword = generatedPassword.slice(0, length)
    return finalPassword
}

export const postResData = async (data, cognitoISP, userPoolId, tenantId) => {
  console.log('postResData Input:', data);

  // Domain Restriction check — validate email domain before creating user
  // Checks both tenant-level and policy-level allowed_domains
  if (data.email && process.env.AMFACONFIG_TABLE && tenantId) {
    try {
      // Fetch tenant-level config
      const configResult = await dynamodb.send(new GetItemCommand({
        TableName: process.env.AMFACONFIG_TABLE,
        Key: { id: { S: tenantId }, configtype: { S: 'amfaConfigs' } },
      }));
      let tenantAllowedDomains = null;
      if (configResult.Item?.value?.S) {
        const config = JSON.parse(configResult.Item.value.S);
        tenantAllowedDomains = config.allowed_domains;
      }

      // First check tenant-level restriction
      const tenantCheck = validateEmailDomain(data.email, tenantAllowedDomains);
      if (!tenantCheck.allowed) {
        throw new DomainRestrictionError(tenantCheck.error);
      }

      // Then check policy-level restriction (if user has groups assigned)
      if (data.groups && data.groups.length > 0) {
        const policiesResult = await dynamodb.send(new GetItemCommand({
          TableName: process.env.AMFACONFIG_TABLE,
          Key: { id: { S: tenantId }, configtype: { S: 'amfaPolicies' } },
        }));
        if (policiesResult.Item?.value?.S) {
          const policies = JSON.parse(policiesResult.Item.value.S);
          for (const groupName of data.groups) {
            const policy = policies[groupName];
            if (policy && policy.allowed_domains && policy.allowed_domains.length > 0) {
              const policyCheck = validateEmailDomain(data.email, policy.allowed_domains);
              if (!policyCheck.allowed) {
                throw new DomainRestrictionError(policyCheck.error);
              }
            }
          }
        }
      }
    } catch (err) {
      if (err.code === 'DOMAIN_RESTRICTED') {
        throw err; // Re-throw domain restriction errors
      }
      console.warn('Domain restriction check failed (non-blocking):', err.message);
    }
  }

  const groups = [];
  const attributes = [];
  Object.keys(data).map(key => {
    switch (key.toLowerCase()) {
      case 'locale':
      case 'profile':
      case 'given_name':
      case 'family_name':
      case 'name':
      case 'middle_name':
      case 'picture':
      case 'gender':
      case 'birthdate':
      // case 'address':
        if (data[key]) {
          attributes.push({ "Name": key.toLowerCase(), "Value": data[key] });
        }
        break;
      case 'email':
        if (data[key]) {
          attributes.push({ "Name": key.toLowerCase(), "Value": data[key].toLowerCase() });
          attributes.push({ "Name": 'email_verified', "Value": 'true' });
        }
        break;
      case 'phone_number':
        if (data[key]) {
          attributes.push({ "Name": key.toLowerCase(), "Value": data[key] });
          attributes.push({ "Name": 'phone_number_verified', "Value": 'true' });
        }
        break;
      // case 'email_verified':
      case 'phone_number_verified':
        if (data[key]) {
          attributes.push({ "Name": key.toLowerCase(), "Value": data[key] ? 'true' : 'false' });
        }
        break;
      case 'groups':
        groups.push(...data[key]);
        break;
      case 'alter-email':
      case 'voice-number':
        if (data[key]) {
          attributes.push({ "Name": `custom:${key}`, "Value": data[key] });
        }
        break;
      default:
        break;
    }
    return key;
  });

  // to allow using email login, amfa has to set user email to verified
  attributes.push({ "Name": 'email_verified', "Value": 'true' });

  attributes.push({ "Name": 'nickname', "Value": data['given_name'] + ' ' + data['family_name'] });

  const params = {
    Username: data['email'].replace('@', '_').replace('.', '_').toLowerCase(),
    ...(!data.notify && { MessageAction: 'SUPPRESS' }),
    TemporaryPassword: generatePassword(true, true, true, true, 10),//data.password,
    UserAttributes: attributes,
    UserPoolId: userPoolId,
    DesiredDeliveryMediums: ['EMAIL'],
  }

  const resData = await cognitoISP.send(new AdminCreateUserCommand(params));
  const item = resData.User;

  if (item) {

    if (groups && groups.length > 0) {
      try {
        await assignApplications(groups, item.Username, cognitoISP, userPoolId);
      }
      catch (err) {
        console.log('create user - assignApplications/groups Error:', err);
      }
    }

    try {
      await cognitoISP.send(new AdminLinkProviderForUserCommand({
        UserPoolId: userPoolId,
        DestinationUser: {
          ProviderName: 'Cognito',
          ProviderAttributeName: 'email',
          ProviderAttributeValue: data['email'].toLowerCase(),
        },
        SourceUser: {
          ProviderName: 'apersona',
          ProviderAttributeName: 'email',
          ProviderAttributeValue: data['email'].toLowerCase(),
        }
      }))
    }
    catch (err) {
      console.log('create user - AdminLinkProviderForUser Error:', err);
    }

    const email_verified = item.Attributes.find(attr => attr.Name === "email_verified")?.Value;
    const phone_number_verified = item.Attributes.find(attr => attr.Name === "phone_number_verified")?.Value;

    const directMappingArrtibutes = [
      'email', 'phone_number', 'locale', 'sub', 'profile', 'given_name', 'family_name',
      'nickname', 'name', 'middle_name', 'picture', 'profile', 'gender', 'birthdate'/*, 'address'*/];
    const filteredAttributs = item.Attributes.filter(el => directMappingArrtibutes.includes(el.Name));
    const result = Object.fromEntries(filteredAttributs.map(el => [el.Name, el.Value]))

    return {
      id: item.Username,
      username: item.Username,
      enabled: item.Enabled,
      status: item.UserStatus,
      email_verified: email_verified === 'true' ? true : false,
      phone_number_verified: phone_number_verified === 'true' ? true : false,
      groups: groups ? groups : null,
      ...result,
    }
  }
}

export default postResData;